<script setup lang="ts">import{onMounted,ref}from'vue';import{storeToRefs}from'pinia';import{useAuthorizationStore}from'../runtime/authorization-store';const props=defineProps<{productId:string}>();const store=useAuthorizationStore();const{productDetail,plans,options,resolution,loading,error,canWrite}=storeToRefs(store);const selectedPlans=ref<string[]>([]),customerId=ref('');async function link(){await store.addProductToPlans(props.productId,selectedPlans.value);selectedPlans.value=[]}async function check(){if(customerId.value)await store.resolve(customerId.value,props.productId)}onMounted(async()=>{await Promise.all([store.load('plans'),store.loadProductDetail(props.productId)])})</script>
<template><section class="authorization-panel"><div v-if="loading" class="panel-state">正在加载商品授权…</div><div v-else-if="error" class="panel-state error">{{error}}</div><template v-else-if="productDetail"><div class="summary"><div><strong>{{productDetail.plans.length}}</strong><span>命中方案</span></div><div><strong>{{productDetail.specials.length}}</strong><span>特殊授权</span></div></div><section class="panel-card"><header><h2>授权方案</h2><div v-if="canWrite" class="linker"><select v-model="selectedPlans" multiple aria-label="选择关联授权方案"><option v-for="p in plans.items" :key="p.id" :value="p.id">{{p.code}} · {{p.name}}</option></select><button :disabled="!selectedPlans.length" @click="link">关联方案</button></div></header><table><thead><tr><th>方案名称</th><th>编码</th><th>适用客户</th><th>包含商品</th><th>状态</th><th>创建时间</th></tr></thead><tbody><tr v-for="p in productDetail.plans" :key="p.id"><td>{{p.name}}</td><td>{{p.code}}</td><td>{{p.customerIds.length}} 个</td><td>{{p.productCount}} 个</td><td>{{p.status==='enabled'?'启用':'停用'}}</td><td>{{p.createdAt.slice(0,16).replace('T',' ')}}</td></tr><tr v-if="!productDetail.plans.length"><td colspan="6">当前商品没有命中授权方案</td></tr></tbody></table></section><section class="panel-card"><h2>客户特殊授权</h2><table><thead><tr><th>客户</th><th>类型</th><th>有效期</th><th>备注</th></tr></thead><tbody><tr v-for="s in productDetail.specials" :key="s.id"><td>{{s.customerName}}</td><td>{{s.type==='prohibited'?'禁止':s.type==='visible-only'?'仅可见':'可见+可订'}}</td><td>{{s.startsAt.slice(0,16).replace('T',' ')}} ～ {{s.endsAt?s.endsAt.slice(0,16).replace('T',' '):'永久'}}</td><td>{{s.note||'—'}}</td></tr><tr v-if="!productDetail.specials.length"><td colspan="4">当前商品没有特殊授权</td></tr></tbody></table></section><section class="panel-card resolver"><h2>授权结果检查</h2><p>使用当前可控模拟时钟，结果会说明命中来源；非启用客户和非上架商品优先拒绝。</p><select v-model="customerId"><option value="">选择客户</option><option v-for="c in options.customers" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}（{{c.status}}）</option></select><button :disabled="!customerId" @click="check">检查结果</button><div v-if="resolution" class="result"><strong>{{resolution.visible?'可见':'不可见'}} / {{resolution.orderable?'可订':'不可订'}}</strong><span>原因：{{resolution.reason}}</span><span>来源：{{resolution.sources.map(x=>x.label).join('、')||'无'}}</span></div></section></template></section></template>
<style scoped>.authorization-panel{display:grid;gap:14px}.panel-state,.panel-card{padding:18px;background:#fff;border:1px solid var(--color-border)}.panel-state.error{color:var(--color-danger)}.summary{display:flex;gap:12px}.summary div{display:grid;min-width:150px;padding:14px;background:#f4faf9;border:1px solid #cfe6e3}.summary strong{font-size:24px}.summary span{color:var(--color-muted)}.panel-card header{display:flex;justify-content:space-between;gap:15px}.panel-card h2{margin:0 0 12px;font-size:16px}.linker{display:flex;gap:8px}.linker select{min-width:260px;height:56px}.linker button,.resolver button{padding:7px 12px;background:#fff;border:1px solid var(--color-border-strong);border-radius:4px}.panel-card table{width:100%;border-collapse:collapse}.panel-card th,.panel-card td{padding:10px;text-align:left;border-bottom:1px solid var(--color-border)}.panel-card th{font-size:12px;background:var(--color-table-head)}.resolver select{min-height:36px;min-width:280px;margin-right:8px}.resolver p{color:var(--color-muted)}.result{display:flex;gap:15px;margin-top:12px;padding:12px;background:var(--color-primary-soft)}</style>
